#!/usr/bin/env python3
from pathlib import Path
import argparse,hashlib,yaml,datetime,subprocess
P=argparse.ArgumentParser();P.add_argument('--release',required=True);P.add_argument('--apk',required=True);P.add_argument('--version-name',required=True);P.add_argument('--version-code',required=True);P.add_argument('--commit',default='');P.add_argument('--fingerprint',default='');a=P.parse_args();R=Path(__file__).resolve().parents[1];apk=Path(a.apk);h=hashlib.sha256(apk.read_bytes()).hexdigest();commit=a.commit or subprocess.check_output(['git','rev-parse','HEAD'],cwd=R,text=True).strip();d=R/'artifacts/apk'/a.release;d.mkdir(parents=True,exist_ok=True);obj={'release':a.release,'apk_file':apk.name,'version_name':a.version_name,'version_code':int(a.version_code),'commit':commit,'sha256':h,'size_bytes':apk.stat().st_size,'signing_fingerprint':a.fingerprint,'built_at':datetime.datetime.now().isoformat(),'test_status':'PENDING','download_url':'PENDING_UPLOAD'};(d/'APK_MANIFEST.yaml').write_text(yaml.safe_dump(obj,allow_unicode=True,sort_keys=False),encoding='utf-8');print(d/'APK_MANIFEST.yaml')
